//! Deterministic project-manifest dependency extraction.

use std::collections::BTreeSet;

use pep508_rs::Requirement;
use serde_json::Value as JsonValue;
use toml::Value;

use crate::ingest::normalize_path;
use crate::{MindLeakError, Result};

/// One direct project dependency and the import metadata Cargo exposes.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct Dependency {
    pub name: String,
    pub import_name: String,
    pub local_manifest: Option<String>,
}

/// One Rust library crate declared by its own Cargo manifest.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RustCrate {
    pub name: String,
    pub root_path: String,
}

/// Extract direct dependencies from a supported project manifest.
pub fn extract(path: &str, content: &str) -> Result<Option<Vec<Dependency>>> {
    let file_name = path.replace('\\', "/");
    let file_name = file_name.rsplit('/').next().unwrap_or(file_name.as_str());
    match file_name {
        "Cargo.toml" => cargo_dependencies(path, content).map(Some),
        "package.json" => package_json_dependencies(path, content).map(Some),
        "go.mod" => go_mod_dependencies(path, content).map(Some),
        name if name == "requirements.txt"
            || (name.starts_with("requirements-") && name.ends_with(".txt")) =>
        {
            requirements_txt_dependencies(path, content).map(Some)
        }
        _ => Ok(None),
    }
}

/// Extract the import name and library root that a Cargo manifest declares.
///
/// A default `src/lib.rs` is only a candidate here. Import resolution also
/// requires that artifact to have been ingested as a real file, so a binary-only
/// package never becomes a fabricated library edge.
pub fn rust_crate(path: &str, content: &str) -> Result<Option<RustCrate>> {
    let path = normalize_path(path);
    if path.rsplit('/').next() != Some("Cargo.toml") {
        return Ok(None);
    }
    let manifest: Value = toml::from_str(content)
        .map_err(|error| MindLeakError::Other(format!("invalid {path}: {error}")))?;
    let Some(package_name) = manifest
        .get("package")
        .and_then(Value::as_table)
        .and_then(|package| package.get("name"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|name| !name.is_empty())
    else {
        return Ok(None);
    };
    let library = manifest.get("lib").and_then(Value::as_table);
    let name = library
        .and_then(|table| table.get("name"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| package_name.replace('-', "_"));
    let relative_root = library
        .and_then(|table| table.get("path"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|path| !path.is_empty())
        .unwrap_or("src/lib.rs");
    let Some(root_path) = manifest_relative_path(&path, relative_root) else {
        return Ok(None);
    };
    Ok(Some(RustCrate { name, root_path }))
}

fn manifest_relative_path(manifest_path: &str, relative: &str) -> Option<String> {
    let relative = normalize_path(relative);
    if relative.starts_with('/') || matches!(relative.as_bytes().get(1), Some(b':')) {
        return None;
    }
    let mut segments: Vec<&str> = manifest_path
        .rsplit_once('/')
        .map(|(directory, _)| directory.split('/').collect())
        .unwrap_or_default();
    for segment in relative.split('/') {
        match segment {
            "" | "." => {}
            ".." => {
                segments.pop()?;
            }
            segment => segments.push(segment),
        }
    }
    (!segments.is_empty()).then(|| segments.join("/"))
}

fn cargo_dependencies(path: &str, content: &str) -> Result<Vec<Dependency>> {
    let manifest: Value = toml::from_str(content)
        .map_err(|error| MindLeakError::Other(format!("invalid {path}: {error}")))?;
    let mut dependencies = BTreeSet::new();
    for section in ["dependencies", "dev-dependencies", "build-dependencies"] {
        collect_cargo_table(path, manifest.get(section), &mut dependencies);
    }
    if let Some(targets) = manifest.get("target").and_then(Value::as_table) {
        for target in targets.values() {
            for section in ["dependencies", "dev-dependencies", "build-dependencies"] {
                collect_cargo_table(path, target.get(section), &mut dependencies);
            }
        }
    }
    Ok(dependencies.into_iter().collect())
}

fn collect_cargo_table(manifest_path: &str, value: Option<&Value>, out: &mut BTreeSet<Dependency>) {
    let Some(dependencies) = value.and_then(Value::as_table) else {
        return;
    };
    for (alias, specification) in dependencies {
        let name = specification
            .as_table()
            .and_then(|table| table.get("package"))
            .and_then(Value::as_str)
            .unwrap_or(alias)
            .trim()
            .to_string();
        if name.is_empty() {
            continue;
        }
        let import_name = alias.replace('-', "_");
        let local_manifest = specification
            .as_table()
            .and_then(|table| table.get("path"))
            .and_then(Value::as_str)
            .and_then(|path| manifest_relative_path(manifest_path, path))
            .map(|path| format!("{path}/Cargo.toml"));
        out.insert(Dependency {
            name,
            import_name,
            local_manifest,
        });
    }
}

fn package_json_dependencies(path: &str, content: &str) -> Result<Vec<Dependency>> {
    let manifest: JsonValue = serde_json::from_str(content)
        .map_err(|error| MindLeakError::Other(format!("invalid {path}: {error}")))?;
    if !manifest.is_object() {
        return Err(MindLeakError::Other(format!(
            "invalid {path}: root must be an object"
        )));
    }
    let mut names = BTreeSet::new();
    for section in [
        "dependencies",
        "devDependencies",
        "peerDependencies",
        "optionalDependencies",
    ] {
        if let Some(dependencies) = manifest.get(section).and_then(JsonValue::as_object) {
            names.extend(
                dependencies
                    .keys()
                    .filter(|name| !name.trim().is_empty())
                    .cloned(),
            );
        }
    }
    Ok(to_dependencies(names))
}

fn go_mod_dependencies(path: &str, content: &str) -> Result<Vec<Dependency>> {
    let mut names = BTreeSet::new();
    let mut in_require_block = false;
    for raw_line in content.lines() {
        let line = raw_line.split("//").next().unwrap_or("").trim();
        if line.is_empty() {
            continue;
        }
        if in_require_block {
            if line == ")" {
                in_require_block = false;
                continue;
            }
            let name = line.split_whitespace().next().unwrap_or("");
            if name.is_empty() || name == "(" {
                return Err(MindLeakError::Other(format!(
                    "invalid {path}: malformed require block"
                )));
            }
            names.insert(name.to_string());
            continue;
        }
        let Some(rest) = line.strip_prefix("require ") else {
            continue;
        };
        let rest = rest.trim();
        if rest == "(" {
            in_require_block = true;
            continue;
        }
        let name = rest.split_whitespace().next().unwrap_or("");
        if name.is_empty() {
            return Err(MindLeakError::Other(format!(
                "invalid {path}: malformed require directive"
            )));
        }
        names.insert(name.to_string());
    }
    if in_require_block {
        return Err(MindLeakError::Other(format!(
            "invalid {path}: unclosed require block"
        )));
    }
    Ok(to_dependencies(names))
}

fn requirements_txt_dependencies(path: &str, content: &str) -> Result<Vec<Dependency>> {
    let mut names = BTreeSet::new();
    for raw_line in content.lines() {
        let line = raw_line.trim();
        if line.is_empty()
            || line.starts_with('#')
            || line.starts_with('-')
            || line.starts_with('.')
            || line.starts_with('/')
            || line.starts_with("git+")
            || line.starts_with("http://")
            || line.starts_with("https://")
        {
            continue;
        }
        let line = line.split(" #").next().unwrap_or(line).trim();
        let requirement = line.parse::<Requirement>().map_err(|error| {
            MindLeakError::Other(format!("invalid {path} requirement {line:?}: {error}"))
        })?;
        names.insert(requirement.name.to_string());
    }
    Ok(to_dependencies(names))
}

fn to_dependencies(names: BTreeSet<String>) -> Vec<Dependency> {
    names.into_iter().map(Dependency::external).collect()
}

impl Dependency {
    fn external(name: String) -> Self {
        Self {
            import_name: name.clone(),
            name,
            local_manifest: None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_cargo_package_declares_its_default_rust_crate() {
        let found = rust_crate(
            "crates/dependency/Cargo.toml",
            "[package]\nname = \"dependency-crate\"\nversion = \"0.1.0\"\n",
        )
        .unwrap();

        assert_eq!(
            found,
            Some(RustCrate {
                name: "dependency_crate".to_string(),
                root_path: "crates/dependency/src/lib.rs".to_string(),
            })
        );
    }

    #[test]
    fn a_local_cargo_dependency_keeps_its_import_alias_and_manifest_path() {
        let found = extract(
            "crates/consumer/Cargo.toml",
            "[dependencies]\nstorage = { package = \"mindleak-storage\", path = \"../mindleak-storage\" }\n",
        )
        .unwrap()
        .unwrap();

        assert_eq!(
            found,
            vec![Dependency {
                name: "mindleak-storage".to_string(),
                import_name: "storage".to_string(),
                local_manifest: Some("crates/mindleak-storage/Cargo.toml".to_string()),
            }]
        );
    }

    #[test]
    fn an_explicit_library_name_and_root_override_package_defaults() {
        let found = rust_crate(
            "crates/dependency/Cargo.toml",
            "[package]\nname = \"dependency\"\nversion = \"0.1.0\"\n\
             [lib]\nname = \"public_api\"\npath = \"../shared/api.rs\"\n",
        )
        .unwrap();

        assert_eq!(
            found,
            Some(RustCrate {
                name: "public_api".to_string(),
                root_path: "crates/shared/api.rs".to_string(),
            })
        );
    }

    #[test]
    fn a_library_root_cannot_escape_the_repository() {
        let found = rust_crate(
            "Cargo.toml",
            "[package]\nname = \"root\"\nversion = \"0.1.0\"\n\
             [lib]\npath = \"../outside.rs\"\n",
        )
        .unwrap();

        assert_eq!(found, None);
    }
}
